1|// Session track selection. Pure: no env, no fetch, no audio.
2|import type {
3|  MusicConfig,
4|  MusicManifest,
5|  MusicSelection,
6|  PersistedMusicPrefs,
7|  Rng,
8|  SceneSignal,
9|  Track,
10|} from "./music-types";
11|import { compareTrackId, dominantEmotion, rankScored, resolveConfig } from "./music-similarity";
12|import type { RankedTrack } from "./music-similarity";
13|
14|// The one audible-scope filter: playlist-only tracks never enter emotion
15|// selection, so every scope below goes through here.
16|export function audibleTracks(manifest: MusicManifest): Track[] {
17|  return manifest.tracks.filter((t) => t.playlistOnly !== true);
18|}
19|
20|// Style scope for every pick. A null style means the whole audible set.
21|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
22|  const audible = audibleTracks(manifest);
23|  if (selection.style === null) return audible;
24|  return audible.filter((t) => t.style === selection.style);
25|}
26|
27|// Best match by score, ties to the lower id. A null scene takes the
28|// first track in id order. Skips one id (the ended track) when given.
29|export function bestRanked(
30|  scene: SceneSignal | null,
31|  tracks: Track[],
32|  excludeId?: string | null,
33|  override?: Partial<MusicConfig>,
34|): Track | null {
35|  const eligible =
36|    excludeId === null || excludeId === undefined
37|      ? tracks
38|      : tracks.filter((t) => t.id !== excludeId);
39|  if (eligible.length === 0) return null;
40|  if (scene === null) return [...eligible].sort(compareTrackId)[0] ?? null;
41|  return rankScored(scene, eligible, override)[0]?.track ?? null;
42|}
43|
44|// Next track: the next same-emotion track in score order across the whole
45|// style, wrapping and skipping the current. With no other same-emotion
46|// track, the best same-style track overall. A null scene cycles the style
47|// set in id order. One track or none gives null.
48|export function nextTrack(
49|  scene: SceneSignal | null,
50|  manifest: MusicManifest,
51|  currentTrackId: string | null,
52|  override?: Partial<MusicConfig>,
53|  selection?: MusicSelection | null,
54|): Track | null {
55|  const scope = candidatesFor(selection ?? { style: null }, manifest);
56|  if (scope.length <= 1) return null;
57|  const config = resolveConfig(override);
58|  if (scene === null) {
59|    const ids = [...scope].sort(compareTrackId);
60|    const at = ids.findIndex((t) => t.id === currentTrackId);
61|    return ids[(at + 1) % ids.length] as Track;
62|  }
63|  const ranked = rankScored(scene, scope, config).map((entry) => entry.track);
64|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
65|  const others = same.filter((t) => t.id !== currentTrackId);
66|  if (others.length > 0) {
67|    const at = same.findIndex((t) => t.id === currentTrackId);
68|    if (at >= 0) return same[(at + 1) % same.length] as Track;
69|    return same[0] as Track;
70|  }
71|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
72|}
73|
74|export interface ScheduledDraw {
75|  cands: Track[];
76|  scene: SceneSignal | null;
77|  currentId: string | null;
78|  currentStartedSec: number;
79|  nowSec: number;
80|  rng: Rng;
81|  override?: Partial<MusicConfig>;
82|}
83|
84|// The one scheduled draw: same-style tracks with the scene's dominant
85|// emotion (or the whole style set when none matches), kept within
86|// randomTolerance of the best. The current track stays when eligible
87|// with no rng call; otherwise the draw runs first (one rng call, its
88|// pick discarded under the min-track hold), matching evaluateRandom.
89|export function selectScheduled(draw: ScheduledDraw): Track | null {
90|  const { cands, scene, currentId, rng } = draw;
91|  if (cands.length === 0 || scene === null) return null;
92|  const config = resolveConfig(draw.override);
93|  const ranked = rankScored(scene, cands, config);
94|  const dom = dominantEmotion(scene);
95|  const pool = ranked.filter((entry) => entry.track.emotion === dom);
96|  const kept = pool.length > 0 ? pool : ranked;
97|  const best = kept[0]?.score ?? 0;
98|  const eligible = kept.filter((entry) => entry.score >= best - config.randomTolerance);
99|  const current = currentId !== null ? eligible.find((entry) => entry.track.id === currentId) : undefined;
100|  if (current) return current.track;
101|  const rest = eligible.filter((entry) => entry.track.id !== currentId);
102|  const drawFrom = rest.length > 0 ? rest : eligible;
103|  if (drawFrom.length === 0) return null;
104|  const picked = (drawFrom[Math.floor(rng() * drawFrom.length)] as RankedTrack).track;
105|  if (currentId !== null && draw.nowSec - draw.currentStartedSec < config.minTrackSec) return null;
106|  return picked;
107|}
108|
109|// True when the style has at least one emotion-selectable track. The style
110|// selector uses this, so a style with only playlist tracks stays hidden.
111|export function styleHasTracks(manifest: MusicManifest, style: string): boolean {
112|  return audibleTracks(manifest).some((t) => t.style === style);
113|}
114|
115|// Session defaults on load. A stored style with no tracks falls back to
116|// the first style that has any.
117|export function resolveInitialSelection(
118|  manifest: MusicManifest,
119|  persisted: PersistedMusicPrefs | null,
120|): MusicSelection {
121|  const fallback = manifest.styles.find((s) => styleHasTracks(manifest, s.id))?.id ?? null;
122|  const style =
123|    persisted?.style !== null &&
124|    persisted?.style !== undefined &&
125|    styleHasTracks(manifest, persisted.style)
126|      ? persisted.style
127|      : fallback;
128|  return { style };
129|}
130|
131|// Style change from user action: the best match for the scene in the new
132|// style by score. Never crosses styles. Null when the style has no tracks.
133|export function requestStyleChange(
134|  manifest: MusicManifest,
135|  style: string,
136|  scene: SceneSignal | null,
137|  override?: Partial<MusicConfig>,
138|): { track: Track } | null {
139|  const scoped = candidatesFor({ style }, manifest);
140|  if (scoped.length === 0) return null;
141|  const track = bestRanked(scene, scoped, null, override);
142|  return track ? { track } : null;
143|}

